style.css:
@-moz-document url("https://www.roblox.com/home") {
/* 
    Inspired by srecko on YouTube - 
    https://www.youtube.com/watch?v=vjv95GqetOs
    */

    /*
    Hide the "Recommended For You" game grid
    Code by CoconutJade
    */
    div:nth-child(-2n+5):not(:first-child) > .game-grid {
        display: none !important;
    }
    div.game-grid.home-game-grid {
        display: none !important;
    }

    /*
    Hide "Today's Picks"
    Code by CoconutJade
    */
    /*.game-sort-carousel-wrapper:nth-child(2) {
      display: none !important;
    }*/
    .scrollable-carousel {
			display: none !important;
    }

    /*
    Hide "Recommended For You" labels while keeping "Continue" and "Favorites"
    Code by CoconutJade
    */
    div:nth-child(-1n+6):not(:first-child)>  .home-sort-header-container .css-9h4h37-textIconRow {
      display: none !important;
    }
		/*div:nth-child(6) > .container-header > h2 {
      display: none !important;
    }
    div:nth-child(4) > .container-header {
      display: none !important;
    }*/

		/*
    Hide the "Sponsored" section
		Code by CoconutJade
    */
    .wide-game-tile-carousel:nth-child(2) {
			display: none !important;
    }
}
